        c = new keepMyEther();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        uint256 cBalBefore = address(c).balance;
        uint256 callerBalBefore;
        try c.balances(caller) returns (uint256 __r) { callerBalBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint256 cBalAfter = address(c).balance;
        uint256 callerBalAfter;
        try c.balances(caller) returns (uint256 __r) { callerBalAfter = __r; } catch { return; }
        assertTrue(callerBalAfter <= callerBalBefore && (!reverted ? callerBalAfter == 0 : true) && (cBalBefore >= cBalAfter || cBalBefore - cBalAfter <= callerBalBefore));
